import { createMemo, createSignal, createUniqueId, For, Show, type JSX } from "solid-js"
import { parseUnifiedPatch, summarizeFileChanges } from "../file-change-diff"
import { CustomSelect } from "../../ui/custom-select"
import { Icon, type IconName } from "../../ui/icon"
import { Markdown } from "./markdown"
import "../../styles/workspace-shell.css"

type CompanionTab = "activity" | "running" | "changes" | "context"
const tabs: readonly CompanionTab[] = ["activity", "changes", "context"]
const allTurnsValue = "all-session-changes"
const tabLabel = (tab: CompanionTab) => `${tab[0]!.toUpperCase()}${tab.slice(1)}`
const countFormat = new Intl.NumberFormat("en-US")
const categories = [["system", "System"], ["tools", "Tools"], ["user", "User"], ["assistant", "Assistant"], ["reasoning", "Reasoning"], ["toolCalls", "Tool calls"], ["other", "Other"]] as const

export type SharedToolStepItem = { readonly id: string; readonly name: string; readonly status: "streaming" | "running" | "completed" | "failed"; readonly summary?: string; readonly duration?: string; readonly inputText?: string; readonly outputText?: string; readonly errorText?: string; readonly markdown?: boolean }
export type SharedFileChangeItem = { readonly path: string; readonly patch: string; readonly additions: number; readonly deletions: number }
type SharedRevert = { readonly staged: boolean; readonly busy?: boolean; readonly summary?: string; readonly error?: string; readonly onStage: () => void; readonly onCommit: () => void; readonly onClear: () => void }

function SharedRevertControls(props: { readonly revert: SharedRevert }): JSX.Element {
  return <div class="rl-revert"><Show when={props.revert.staged} fallback={<button type="button" class="rl-btn" disabled={props.revert.busy} onClick={props.revert.onStage}>Revert changes…</button>}><Show when={props.revert.summary}><p>{props.revert.summary}</p></Show><button type="button" class="rl-btn" disabled={props.revert.busy} onClick={props.revert.onCommit}>Confirm revert</button><button type="button" class="rl-btn" disabled={props.revert.busy} onClick={props.revert.onClear}>Cancel</button></Show><Show when={props.revert.error}><p role="alert">{props.revert.error}</p></Show></div>
}

type SharedRadioOption = { readonly value: string; readonly label: string; readonly disabled?: boolean; readonly icon?: IconName }

export function SharedRadioGroup(props: { readonly label: string; readonly options: readonly SharedRadioOption[]; readonly value: string; readonly disabled?: boolean; readonly onChange: (value: string) => void }): JSX.Element {
  return <div class="rl-radios" data-inline="true" role="radiogroup" aria-label={props.label}><For each={props.options}>{(option) => <button type="button" role="radio" class="rl-radio" aria-checked={props.value === option.value} data-has-icon={option.icon ? "true" : undefined} disabled={props.disabled || option.disabled} onClick={() => props.onChange(option.value)}><i aria-hidden="true"></i><Show when={option.icon}>{(icon) => <Icon name={icon()} size={14} />}</Show><span>{option.label}</span></button>}</For></div>
}

type ActivityTone = "failed" | "done" | "active"

function activityTone(status: string, exit?: number): ActivityTone {
  if ((exit !== undefined && exit !== 0) || /fail|error|exit(ed)? [1-9]/i.test(status)) return "failed"
  if (exit === 0 || /^(completed|done|exited 0)/i.test(status)) return "done"
  return "active"
}

const shellIcons: Record<ActivityTone, IconName> = { failed: "alert", done: "check", active: "terminal" }
const taskIcons: Record<ActivityTone, IconName> = { failed: "alert", done: "check", active: "team" }

function SharedActivityRow(props: { readonly tone: ActivityTone; readonly kind: "shell" | "task"; readonly onOpen?: () => void; readonly children: JSX.Element }): JSX.Element {
  const body = () => <><span class="rl-activity-row__icon" aria-hidden="true"><Icon name={(props.kind === "shell" ? shellIcons : taskIcons)[props.tone]} size={16} /></span><span class="rl-activity-row__body">{props.children}</span></>
  return <Show when={props.onOpen} fallback={<div class="rl-activity-row" data-state={props.tone}>{body()}</div>}>{(open) => <button type="button" class="rl-activity-row" data-state={props.tone} onClick={open()}>{body()}<span class="rl-activity-row__chevron" aria-hidden="true"><Icon name="chevron-right" size={16} /></span></button>}</Show>
}

export function SharedToolDisclosure(props: { readonly tools: readonly SharedToolStepItem[]; readonly durationLabel?: string; readonly lastSummary?: string; readonly streaming?: boolean; readonly reasoning?: string; readonly defaultOpen?: boolean }): JSX.Element {
  const [open, setOpen] = createSignal(props.defaultOpen ?? false)
  const last = () => props.tools.at(-1)
  return <section><button type="button" class="transcript-tools__button rl-chip" aria-expanded={open()} onClick={() => setOpen((value) => !value)}><span class="rl-disclosure-icon" aria-hidden="true"><Icon name={props.streaming ? "sparkles" : props.tools.some((item) => item.status === "failed") ? "alert" : "terminal"} size={16} /></span><span>{props.streaming ? "Working…" : props.durationLabel ? `Worked for ${props.durationLabel}` : "Worked"} · {props.tools.length} {props.tools.length === 1 ? "tool" : "tools"}</span><Show when={props.lastSummary ?? last()}><span class="rl-chip-last" data-tone={last()?.status === "failed" ? "bad" : props.streaming ? "busy" : undefined}>{props.lastSummary ?? (last() ? `${last()!.name}${last()!.inputText ? ` ${last()!.inputText!.replace(/\s+/g, " ").slice(0, 56)}` : ""}` : "")}</span></Show><span class="rl-disclosure-chev" aria-hidden="true"><Icon name="chevron-right" size={16} /></span></button><Show when={open()}><div class="rl-disclosure-card rl-tools-card"><Show when={props.reasoning}>{(reasoning) => <div class="rl-card-markdown"><Markdown text={reasoning()} /></div>}</Show><ol class="rl-steps"><For each={props.tools}>{(item) => <li class="rl-step-card" data-status={item.status}><div class="rl-step-head"><span class="rl-step-icon" aria-hidden="true"><Icon name={item.status === "completed" ? "check" : item.status === "failed" ? "alert" : "sparkles"} size={14} /></span><strong>{item.name}</strong><Show when={item.summary}><span class="rl-step-summary">{item.summary}</span></Show><small class="rl-step-meta">{item.status}{item.duration ? ` · ${item.duration}` : ""}</small></div><Show when={item.inputText}><pre class="rl-output"><code>{item.inputText}</code></pre></Show><Show when={item.outputText}>{(output) => item.markdown ? <div class="rl-card-markdown"><Markdown text={output()} /></div> : <pre class="rl-output"><code>{output()}</code></pre>}</Show><Show when={item.status === "running" || item.status === "streaming"}><div class="rl-indeterminate" aria-hidden="true"><span /></div></Show><Show when={item.errorText}><div class="rl-step-error" role="status"><Icon name="alert" size={14} /><span>{item.errorText}</span></div></Show></li>}</For></ol></div></Show></section>
}

export function SharedReasoningDisclosure(props: { readonly text: string; readonly durationLabel?: string; readonly streaming?: boolean; readonly defaultOpen?: boolean }): JSX.Element {
  const [open, setOpen] = createSignal(props.defaultOpen ?? false)
  return <details class="transcript-reasoning rl-reason-disclosure" open={open()}><summary aria-expanded={open()} onClick={(event) => { event.preventDefault(); setOpen(!open()) }}><span class="transcript-reasoning__tag"><Icon name={props.streaming ? "sparkles" : "check"} size={16} /></span><span>Thought{props.durationLabel ? ` · ${props.durationLabel}` : ""}</span><span class="transcript-reasoning__hint">{open() ? "Hide" : "Show"} details</span><span class="rl-disclosure-chev" aria-hidden="true"><Icon name="chevron-right" size={16} /></span></summary><Show when={open()}><div class="transcript-reasoning__body rl-reason rl-disclosure-card"><Markdown text={props.text} /></div></Show></details>
}

export function SharedEditedFilesCard(props: { readonly files: readonly SharedFileChangeItem[]; readonly defaultOpen?: boolean; readonly title?: string; readonly onViewChanges?: (path?: string) => void; readonly onUndo?: () => void; readonly undoDisabled?: boolean; readonly undoLabel?: string; readonly footerNote?: string; readonly revert?: SharedRevert }): JSX.Element {
  const [open, setOpen] = createSignal(props.defaultOpen ?? false)
  const totals = createMemo(() => summarizeFileChanges(props.files))
  const title = () => props.title ?? `${props.files.length} ${props.files.length === 1 ? "file" : "files"} changed`
  return <section class="ws-changes rl-edited-card file-change-card" aria-label="Captured file changes" data-open={open() ? "true" : undefined} data-panel={open() || props.revert || props.footerNote ? "true" : undefined}><div class="rl-edited-summary"><button type="button" class="rl-edited-disclosure" aria-expanded={open()} onClick={() => setOpen((value) => !value)}><Icon name="file" size={14} /><span class="rl-edited-title">{title()}</span><span class="rl-diff-total"><span class="ws-add">+{totals().additions}</span><span class="ws-del">−{totals().deletions}</span></span><span class="rl-disclosure-chev" aria-hidden="true"><Icon name="chevron-right" size={14} /></span></button><Show when={props.onViewChanges || props.onUndo}><div class="rl-edited-actions"><Show when={props.onViewChanges}><button type="button" class="rl-btn" onClick={() => props.onViewChanges?.()}><Icon name="file" size={14} />View changes</button></Show><Show when={props.onUndo}><button type="button" class="rl-btn" disabled={props.undoDisabled} onClick={() => props.onUndo?.()}><Icon name="reset" size={14} />{props.undoLabel ?? "Undo…"}</button></Show></div></Show></div><Show when={open()}><div class="ws-card-body"><div class="rl-edited-files"><For each={props.files}>{(file) => <button type="button" class="rl-edited-file" onClick={() => props.onViewChanges?.(file.path)}><Icon name="file" size={14} /><code>{file.path}</code><span class="ws-delta"><span class="ws-add">+{file.additions}</span> <span class="ws-del">−{file.deletions}</span></span></button>}</For></div></div></Show><Show when={props.revert}>{(revert) => <SharedRevertControls revert={revert()} />}</Show><Show when={props.footerNote}><p class="rl-quiet">{props.footerNote}</p></Show></section>
}

export function SharedActivitySurface(props: { readonly workspaceLabel?: string; readonly shells: readonly { readonly id: string; readonly command: string; readonly status: string; readonly cwd?: string; readonly ownerSessionID?: string; readonly pid?: number; readonly exit?: number }[]; readonly subagents: readonly { readonly sessionID: string; readonly agent: string; readonly description: string; readonly state: string; readonly model: string; readonly progressText?: string; readonly questionText?: string; readonly onOpen?: () => void }[]; readonly childSessions?: readonly { readonly id: string; readonly title: string; readonly status: string; readonly onOpen?: () => void }[]; readonly notices?: readonly string[]; readonly changesSummary?: { readonly additions: number; readonly deletions: number; readonly onOpenChanges: () => void }; readonly capabilityNote?: string; readonly onSelectShell?: (shellID?: string) => void; readonly shellOutput?: { readonly shellID: string; readonly output: string; readonly truncated?: boolean; readonly nextCursor?: number; readonly loading?: boolean; readonly error?: string; readonly onLoadMore?: () => void }; readonly subagentNext?: string; readonly loadingMoreSubagents?: boolean; readonly onLoadMoreSubagents?: () => void }): JSX.Element {
  const [shellID, setShellID] = createSignal<string>()
  const selected = () => props.shells.find((shell) => shell.id === shellID())
  return <div class="rl-activity"><Show when={selected()} fallback={<><Show when={props.workspaceLabel}><p>{props.workspaceLabel}</p></Show><section class="rl-activity-group"><h3>Shell processes <span>{props.shells.length}</span></h3><For each={props.shells} fallback={<p>No Session-attributed shells.</p>}>{(shell) => <SharedActivityRow kind="shell" tone={activityTone(shell.status, shell.exit)} onOpen={() => { setShellID(shell.id); props.onSelectShell?.(shell.id) }}><strong>{shell.command}</strong><small>{shell.status}{shell.ownerSessionID ? ` · ${shell.ownerSessionID}` : ""}{shell.cwd ? ` · ${shell.cwd}` : ""}</small></SharedActivityRow>}</For></section><section class="rl-activity-group"><h3>Subagent tasks <span>{props.subagents.length}</span></h3><For each={props.subagents} fallback={<p>No subagent tasks.</p>}>{(task) => <SharedActivityRow kind="task" tone={activityTone(task.state)} onOpen={task.onOpen}><strong>{task.agent} · {task.description}</strong><small>{task.state} · {task.model}</small><Show when={task.progressText}><small>{task.progressText}</small></Show><Show when={task.questionText}><small>{task.questionText}</small></Show></SharedActivityRow>}</For><Show when={props.subagentNext && props.onLoadMoreSubagents}><button type="button" class="rl-btn" disabled={props.loadingMoreSubagents} onClick={props.onLoadMoreSubagents}>Load older subagents</button></Show></section><section class="rl-activity-group"><h3>Loaded child Sessions <span>{props.childSessions?.length ?? 0}</span></h3><For each={props.childSessions} fallback={<p>No loaded child Sessions.</p>}>{(child) => <SharedActivityRow kind="task" tone={activityTone(child.status)} onOpen={child.onOpen}><strong>{child.title}</strong><small>{child.status}</small></SharedActivityRow>}</For></section><Show when={props.changesSummary}>{(changes) => <section class="rl-activity-group"><h3>Recent activity</h3><button type="button" class="rl-btn" onClick={changes().onOpenChanges}>Changes · +{changes().additions} / −{changes().deletions}</button></section>}</Show><For each={props.notices}>{(notice) => <p>{notice}</p>}</For></>}>{(shell) => <div class="rl-pane-detail"><button type="button" class="rl-btn" onClick={() => { setShellID(undefined); props.onSelectShell?.() }}>Back to activity</button><h3>{shell().command}</h3><dl class="rl-meta"><dt>Status</dt><dd>{shell().status}</dd><Show when={shell().cwd}><dt>Directory</dt><dd>{shell().cwd}</dd></Show><Show when={shell().ownerSessionID}><dt>Owner Session</dt><dd>{shell().ownerSessionID}</dd></Show><Show when={shell().pid !== undefined}><dt>PID</dt><dd>{shell().pid}</dd></Show><Show when={shell().exit !== undefined}><dt>Exit</dt><dd>{shell().exit}</dd></Show></dl><Show when={props.shellOutput?.shellID === shell().id && props.shellOutput}>{(output) => <><pre class="rl-output"><code>{output().output || "No shell output captured."}</code></pre><Show when={output().truncated}><p>Earlier output was truncated.</p></Show><Show when={output().error}><p role="alert">{output().error}</p></Show><Show when={output().nextCursor !== undefined && output().onLoadMore}><button type="button" class="rl-btn" disabled={output().loading} onClick={output().onLoadMore}>Load more output</button></Show></>}</Show><Show when={props.capabilityNote}><p>{props.capabilityNote}</p></Show></div>}</Show></div>
}

export function SharedChangesSurface(props: { readonly files: readonly SharedFileChangeItem[]; readonly selectedPath?: string; readonly onSelectFile?: (path: string) => void; readonly onRefresh?: () => void; readonly refreshing?: boolean; readonly scopeLabel?: string; readonly scopeTruth?: string; readonly turns?: readonly { readonly id: string; readonly label: string; readonly files: readonly SharedFileChangeItem[] }[]; readonly selectedTurnID?: string; readonly onSelectTurn?: (turnID?: string) => void; readonly turnsNotice?: string; readonly onOpenFullChanges?: () => void; readonly fullChangesLabel?: string; readonly revert?: SharedRevert }): JSX.Element {
  const [localPath, setLocalPath] = createSignal<string>()
  const files = () => props.selectedTurnID === undefined ? props.files : props.turns?.find((turn) => turn.id === props.selectedTurnID)?.files ?? []
  const totals = createMemo(() => summarizeFileChanges(files()))
  const activeFile = () => files().find((file) => file.path === (props.selectedPath ?? localPath())) ?? files()[0]
  const diff = createMemo(() => { const file = activeFile(); return file ? parseUnifiedPatch(file.patch) : undefined })
  return <div class="rl-changes"><div class="rl-pane-section-heading"><Show when={props.turns?.length || props.selectedTurnID !== undefined} fallback={<strong>{props.scopeLabel ?? "Session changes"}</strong>}><div class="rl-turn-filter"><CustomSelect label="Change scope" sheetTitle="Change scope" sheetSubtitle="Choose which edits to review" placeholder="Turn unavailable" value={props.selectedTurnID ?? allTurnsValue} options={[{ value: allTurnsValue, label: "All Session changes" }, ...(props.turns ?? []).map((turn) => ({ value: turn.id, label: turn.label, detail: `${turn.files.length} ${turn.files.length === 1 ? "file" : "files"}` }))]} onChange={(value) => props.onSelectTurn?.(value === allTurnsValue ? undefined : value)} /></div></Show><span class="rl-diff-total"><span class="ws-add">+{totals().additions}</span> <span class="ws-del">−{totals().deletions}</span></span><Show when={props.onRefresh}><button type="button" class="rl-btn" disabled={props.refreshing} onClick={props.onRefresh}>Refresh</button></Show></div><Show when={props.scopeTruth}><p>{props.scopeTruth}</p></Show><Show when={props.turnsNotice}><p class="rl-quiet">{props.turnsNotice}</p></Show><Show when={props.revert}>{(revert) => <SharedRevertControls revert={revert()} />}</Show><Show when={files().length} fallback={<p>{props.selectedTurnID === undefined ? "No captured file changes for this Session." : props.turns?.some((turn) => turn.id === props.selectedTurnID) ? "No captured file changes in this turn." : "This turn is no longer available."}</p>}><div class="rl-file-jump" aria-label="Changed files"><For each={files()}>{(file) => <button type="button" data-selected={activeFile()?.path === file.path ? "true" : undefined} aria-current={activeFile()?.path === file.path ? "true" : undefined} onClick={() => { setLocalPath(file.path); props.onSelectFile?.(file.path) }}><span class="rl-file-jump__icon" aria-hidden="true"><Icon name="file" size={14} /></span><span class="rl-file-jump__path">{file.path}</span><span class="rl-diff-total"><span class="ws-add">+{file.additions}</span> <span class="ws-del">−{file.deletions}</span></span></button>}</For></div><Show when={activeFile()}>{(file) => <article class="rl-file-diff"><header><strong>{file().path}</strong></header><div class="rl-diff-scroll" tabindex="0" aria-label={`Unified diff for ${file().path}`}><Show when={diff()} fallback={<p>Diff unavailable for this file.</p>}>{(parsed) => <For each={parsed().unified}>{(line) => <div class="rl-diff-line" data-kind={line.kind}><span class="rl-diff-num">{line.kind === "hunk" ? "" : line.oldNumber ?? ""}</span><span class="rl-diff-num">{line.kind === "hunk" ? "" : line.newNumber ?? ""}</span><span class="rl-diff-sign">{line.kind === "added" ? "+" : line.kind === "removed" ? "-" : line.kind === "context" ? " " : "@"}</span><code>{line.text}</code></div>}</For>}</Show></div></article>}</Show></Show><Show when={props.onOpenFullChanges}><button type="button" class="rl-btn rl-changes-open-full" onClick={() => props.onOpenFullChanges?.()}><span class="rl-changes-open-full__icon" aria-hidden="true"><Icon name="file" size={16} /></span><span>{props.fullChangesLabel ?? "Open full changes page"}</span></button></Show></div>
}

export function SharedContextRingButton(props: { readonly fraction?: number; readonly stale?: boolean; readonly label: JSX.Element; readonly ariaLabel: string; readonly ariaDescription?: string; readonly ariaControls?: string; readonly expanded: boolean; readonly class?: string; readonly onClick: () => void }): JSX.Element {
  return <button type="button" class={props.class} aria-label={props.ariaLabel} aria-description={props.ariaDescription} aria-controls={props.ariaControls} aria-expanded={props.expanded} data-level={(props.fraction ?? 0) >= 0.9 ? "danger" : (props.fraction ?? 0) >= 0.7 ? "warn" : "ok"} data-stale={props.stale ? "true" : undefined} onClick={props.onClick}>
    <svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9" pathLength="100" fill="none" stroke="var(--yc-border-strong)" stroke-width="2" /><circle class="rl-ring-value" cx="12" cy="12" r="9" pathLength="100" fill="none" stroke="var(--rl-ring-stroke, var(--yc-green-strong))" stroke-width="2" stroke-dasharray={`${Math.min(100, Math.max(0, (props.fraction ?? 0) * 100))} 100`} /></svg><span>{props.label}</span>
  </button>
}

export function SharedCompanionTabs(props: { readonly active: CompanionTab; readonly class?: string; readonly idPrefix?: string; readonly running?: boolean; readonly onSelect: (tab: CompanionTab) => void; readonly onCloseTab?: (id: CompanionTab) => void; readonly onAddTab?: () => void }): JSX.Element {
  const available = () => props.running ? ["activity", "running", "changes", "context"] as const : tabs
  return <div class={props.class ? `rl-pane-tabs ${props.class}` : "rl-pane-tabs"} role="tablist" aria-label="Session companion">
    <For each={available()}>{(tab, index) => <div class="rl-pane-tab" data-active={props.active === tab ? "true" : undefined}><button type="button" role="tab" aria-selected={props.active === tab} aria-controls={`${props.idPrefix ?? "companion"}-${tab}`} tabindex={props.active === tab ? 0 : -1} onClick={() => props.onSelect(tab)} onKeyDown={(event) => {
      const next = event.key === "Home" ? 0 : event.key === "End" ? available().length - 1 : event.key === "ArrowRight" ? (index() + 1) % available().length : event.key === "ArrowLeft" ? (index() + available().length - 1) % available().length : undefined
      if (next === undefined) return
      event.preventDefault()
      props.onSelect(available()[next]!)
      event.currentTarget.closest('[role="tablist"]')?.querySelectorAll<HTMLButtonElement>('[role="tab"]')[next]?.focus()
    }}>{tabLabel(tab)}</button><Show when={props.onCloseTab}><button type="button" class="rl-pane-tab-close" aria-label={`Close ${tabLabel(tab)} tab`} onClick={(event) => { event.stopPropagation(); props.onCloseTab?.(tab) }}><Icon name="close" size={14} /></button></Show></div>}</For>
  </div>
}

export function SharedContextBreakdownPanel(props: { readonly used?: string; readonly capacity?: string; readonly label?: string; readonly remaining?: number; readonly fraction?: number; readonly draftTokens?: number; readonly modelLabel?: string; readonly nearLimit?: boolean; readonly staleReason?: string; readonly breakdown?: Readonly<Record<(typeof categories)[number][0], number>>; readonly fallbackText?: string; readonly providerLabel?: string; readonly stepDiagnostics?: { readonly uncachedInput: number; readonly output: number; readonly reasoning: number; readonly cacheRead: number; readonly cacheWrite: number; readonly hitRatio?: number; readonly latestInvalidation?: string }; readonly onOpenUsage?: () => void; readonly usageActionLabel?: string; readonly onCompact?: () => void; readonly compactDisabled?: boolean; readonly contextMessagesLabel?: string; readonly contextMessages?: readonly { readonly id: string; readonly role: string; readonly summary: string }[] }): JSX.Element {
  const total = () => categories.reduce((sum, [key]) => sum + (props.breakdown?.[key] ?? 0), 0)
  const share = (value: number) => `${total() > 0 ? (100 * value / total()).toFixed(1) : "0.0"}%`
  const summary = () => [props.remaining === undefined ? undefined : `${countFormat.format(props.remaining)} remaining`, props.label].filter(Boolean).join(" · ")
  const meta = () => [props.providerLabel ? `Provider: ${props.providerLabel}` : undefined, props.modelLabel ? `Model: ${props.modelLabel}` : undefined, props.nearLimit ? "Near context limit." : undefined].filter(Boolean).join(" · ")
  const usedPercent = () => Math.min(100, Math.max(0, (props.fraction ?? 0) * 100))
  return <div class="rl-context-panel">
    <div class="rl-context-window"><p class="companion__context-eyebrow rl-pane-kicker">Active window</p>
      <Show when={props.used} fallback={<p class="rl-context-empty">{props.fallbackText ?? "Context window usage is not reported for the selected model."}</p>}>
        <p class="rl-context-total"><strong class="companion__context-total">{props.used}</strong><Show when={props.capacity}><span class="companion__context-capacity">/ {props.capacity} tokens</span></Show></p>
        <Show when={summary()}><p class="rl-context-summary">{summary()}</p></Show>
        <Show when={props.fraction !== undefined}><div class="rl-context-progress" role="progressbar" aria-label="Context window used" aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(usedPercent())} data-level={usedPercent() >= 90 ? "danger" : usedPercent() >= 70 ? "warn" : "ok"}><span style={{ width: `${usedPercent()}%` }} /></div></Show>
      </Show>
      <Show when={props.draftTokens !== undefined}><p class="rl-draft-estimate">Draft estimate · {countFormat.format(props.draftTokens ?? 0)} tokens</p></Show>
      <Show when={props.staleReason}><p class="rl-context-stale">{props.staleReason}</p></Show>
      <Show when={meta()}><p class="rl-context-meta">{meta()}</p></Show>
      <Show when={props.used}><p class="rl-context-note">Estimated input breakdown by category, separate from provider-reported window tokens and cumulative spend.</p></Show>
    </div>
    <Show when={props.used}><Show when={props.breakdown} fallback={<p class="rl-context-note">Per-category token breakdown is not reported for this turn.</p>}>{(breakdown) => <div class="rl-context-categories"><div class="companion__context-bar" aria-hidden="true"><For each={categories}>{([key]) => <span class="companion__context-bar-segment" data-category={key} aria-hidden="true" style={{ "flex-grow": String(Math.max(0, breakdown()[key])) }} />}</For></div><dl class="companion__context-breakdown" aria-label="Estimated context token breakdown"><For each={categories}>{([key, label]) => <div class="companion__context-row"><dt><span class="companion__context-swatch" data-category={key} aria-hidden="true" />{label}</dt><dd class="companion__context-count">{countFormat.format(breakdown()[key])}</dd><dd class="companion__context-percent">{share(breakdown()[key])}</dd></div>}</For></dl></div>}</Show></Show>
    <Show when={props.stepDiagnostics}>{(diagnostics) => <section class="rl-context-cache"><h3>Step &amp; prompt cache diagnostics</h3><dl class="rl-meta"><dt>Uncached input</dt><dd>{countFormat.format(diagnostics().uncachedInput)}</dd><dt>Output</dt><dd>{countFormat.format(diagnostics().output)}</dd><dt>Reasoning</dt><dd>{countFormat.format(diagnostics().reasoning)}</dd><dt>Cache read</dt><dd>{countFormat.format(diagnostics().cacheRead)}</dd><dt>Cache write</dt><dd>{countFormat.format(diagnostics().cacheWrite)}</dd><Show when={diagnostics().hitRatio !== undefined}><dt>Hit ratio</dt><dd class="rl-context-hit">{((diagnostics().hitRatio ?? 0) * 100).toFixed(1)}%</dd></Show><Show when={diagnostics().latestInvalidation}><dt>Latest invalidation</dt><dd>{diagnostics().latestInvalidation}</dd></Show></dl></section>}</Show>
    <Show when={props.onCompact}><div class="rl-context-actions"><button type="button" class="rl-btn rl-context-compact" disabled={props.compactDisabled} onClick={() => props.onCompact?.()}>Compact context</button></div></Show>
    <Show when={props.onOpenUsage || props.contextMessages !== undefined}><div class="companion__context-footer"><Show when={props.onOpenUsage}><button type="button" class="rl-context-footer-row rl-context-usage" onClick={() => props.onOpenUsage?.()}><span>{props.usageActionLabel ?? "Open Usage · cumulative spend"}</span><Icon name="arrow-up-right" size={14} /></button></Show><Show when={props.contextMessages}>{(messages) => <details class="rl-context-messages"><summary class="rl-context-footer-row"><span>{props.contextMessagesLabel ?? "Retained transcript messages"}</span><span class="rl-context-messages__count">{messages().length}</span><span class="rl-context-messages__chev" aria-hidden="true"><Icon name="chevron-right" size={14} /></span></summary><Show when={messages().length}><ol class="rl-context-message-list"><For each={messages()}>{(message) => <li><strong>{message.role}</strong> · {message.summary}</li>}</For></ol></Show></details>}</Show></div></Show>
  </div>
}

