export function SharedCompactionDivider(props: { readonly completed: boolean; readonly status?: "running" | "pending" | "completed" | "failed" | "cancelled"; readonly label: string; readonly total: string; readonly reduction: number; readonly number: string; readonly items: string }): JSX.Element {
  const state = () => props.status ?? (props.completed ? "completed" : "running")
  const isRunning = () => !props.completed && (state() === "running" || state() === "pending")
  return <div class={`transcript-compaction${props.completed ? " transcript-compaction--completed" : isRunning() ? " transcript-compaction--running" : ""}`} data-status={state()}><div class="transcript-compaction__heading"><span class="transcript-compaction__rule" /><strong class="transcript-compaction__label">{props.label}</strong><span class="transcript-compaction__rule" /></div><Show when={props.completed} fallback={<Show when={isRunning()} fallback={<Show when={props.number || props.items}><p class="transcript-compaction__status">{[props.number, props.items].filter(Boolean).join(" · ")}</p></Show>}><div class="transcript-compaction__running" role="status"><div class="transcript-compaction__progress" aria-hidden="true"><span class="transcript-compaction__indeterminate" /></div><p class="transcript-compaction__status">Compacting conversation context…</p></div></Show>}><div class="transcript-compaction__details"><p class="transcript-compaction__total">{props.total}</p><div class="transcript-compaction__bar" role="img" aria-label={`${props.reduction}% of input tokens removed`}><span class="transcript-compaction__removed" style={{ width: `${Math.max(0, Math.min(100, props.reduction))}%` }} /><span class="transcript-compaction__retained" /></div><p class="transcript-compaction__number">{props.number}</p><Show when={props.items}><p class="transcript-compaction__items">{props.items}</p></Show></div></Show></div>
}

