export type SharedProjectCreateInput = { readonly name: string; readonly masterSessionID: string; readonly memberSessionIDs: readonly string[] }
export type SharedProjectDirectoryInput = { readonly name: string; readonly directory: string; readonly masterTitle?: string; readonly memberSessionIDs: readonly string[] }
type SharedProjectFormOptions = { readonly name?: string; readonly onName?: (name: string) => void; readonly onToggleMember?: (id: string) => void; readonly onCreate?: () => void; readonly onCreateProject?: (input: SharedProjectCreateInput) => void; readonly onCreateProjectInDirectory?: (input: SharedProjectDirectoryInput) => void; readonly onBrowseFolder?: (currentDirectory: string, choose: (directory: string) => void) => void }
export type SharedProjectForm = ReturnType<typeof createSharedProjectForm>

export function createSharedProjectForm(options: SharedProjectFormOptions) {
  const [source, setSource] = createSignal<"existing" | "directory">("existing")
  const [localName, setLocalName] = createSignal("")
  const [query, setQuery] = createSignal("")
  const [masterID, setMasterID] = createSignal<string>()
  const [selectedMembers, setSelectedMembers] = createSignal<readonly string[]>([])
  const [directory, setDirectory] = createSignal("")
  const [masterTitle, setMasterTitle] = createSignal("")
  const [error, setError] = createSignal<string>()
  const name = () => options.name ?? localName()
  const memberIDs = () => source() === "existing" ? selectedMembers().filter((id) => id !== masterID()) : selectedMembers()
  const submitDirectory = () => {
    const trimmedName = name().trim()
    const trimmedDirectory = directory().trim()
    if (!trimmedName || !trimmedDirectory) return setError("Enter a project name and choose a folder first.")
    setError(undefined)
    options.onCreateProjectInDirectory?.({ name: trimmedName, directory: trimmedDirectory, masterTitle: masterTitle().trim() || undefined, memberSessionIDs: memberIDs() })
  }
  const submitExisting = () => {
    if (!options.onCreateProject) return options.onCreate?.()
    const trimmedName = name().trim()
    const master = masterID()
    if (!trimmedName || !master) return setError("Enter a project name and choose a Master Session first.")
    setError(undefined)
    options.onCreateProject({ name: trimmedName, masterSessionID: master, memberSessionIDs: memberIDs() })
  }
  return {
    source, setSource, name, query, setQuery, masterID, memberIDs, directory, setDirectory, masterTitle, setMasterTitle, error,
    setName: (value: string) => { setLocalName(value); options.onName?.(value) },
    chooseMaster: (id: string) => setMasterID(id),
    toggleMember: (id: string) => { setSelectedMembers((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id]); options.onToggleMember?.(id) },
    browse: () => options.onBrowseFolder?.(directory(), (chosen) => { setDirectory(chosen); setSource("directory") }),
    submit: () => { if (source() === "directory") submitDirectory(); else submitExisting() },
  }
}

type SharedProjectMember = { readonly sessionID: string; readonly title: string; readonly state: string }
export type SharedCoordinationProject = { readonly id: string; readonly name: string; readonly masterTitle: string; readonly active: boolean; readonly statusText: string; readonly revision: number; readonly master: SharedProjectMember; readonly members: readonly SharedProjectMember[]; readonly delegatedText?: string; readonly concurrency?: string; readonly openNote: string }
export function SharedProjectsSurface(props: { readonly projects: readonly SharedCoordinationProject[]; readonly selectedID?: string; readonly capabilityScope?: string; readonly refreshing?: boolean; readonly busy?: boolean; readonly notice?: string; readonly creating?: boolean; readonly name?: string; readonly nameError?: string; readonly candidates?: readonly { readonly id: string; readonly title: string; readonly selected: boolean }[]; readonly onRefresh?: () => void; readonly onOpenCreate?: () => void; readonly onName?: (name: string) => void; readonly onToggleMember?: (id: string) => void; readonly onCreate?: () => void; readonly onCancelCreate?: () => void; readonly onSelect: (id: string) => void; readonly onChangeConcurrency: (value: string) => void; readonly onOpenMaster: (sessionID: string) => void; readonly onDeleteProject?: (id: string) => void; readonly concurrencyControl?: (project: SharedCoordinationProject) => JSX.Element; readonly onCreateProject?: (input: SharedProjectCreateInput) => void; readonly onCreateProjectInDirectory?: (input: SharedProjectDirectoryInput) => void; readonly directories?: ReadonlyArray<{ readonly directory: string; readonly name?: string }>; readonly onBrowseFolder?: (currentDirectory: string, choose: (directory: string) => void) => void; readonly form?: SharedProjectForm }): JSX.Element {
  const selected = () => props.projects.find((project) => project.id === props.selectedID)
  const form = props.form ?? createSharedProjectForm(props)
  const directorySource = () => Boolean(props.onCreateProjectInDirectory || props.directories || props.onBrowseFolder)
  const masterCandidates = () => { const needle = form.query().trim().toLowerCase(); return (props.candidates ?? []).filter((candidate) => !needle || candidate.title.toLowerCase().includes(needle) || candidate.id.toLowerCase().includes(needle)) }
  const memberCandidates = () => (props.candidates ?? []).filter((candidate) => form.source() === "directory" || candidate.id !== form.masterID())
  return <div class="relay-settings st-stack"><div class="st-toolbar"><p class="st-count" data-part="st-coord-count">{props.projects.length} project{props.projects.length === 1 ? "" : "s"}</p><div class="ws-row"><Show when={props.onRefresh}><button type="button" class="rl-btn" disabled={props.refreshing} onClick={props.onRefresh}><Icon name="refresh" size={15} /> Refresh</button></Show><Show when={props.onOpenCreate}><button type="button" class="rl-btn" data-action-id="st-coord-new" disabled={props.busy} onClick={props.onOpenCreate}><Icon name="plus" size={15} /> New project</button></Show></div></div><Show when={props.notice}><p class="st-result" role="status">{props.notice}</p></Show><Show when={props.creating}><div class="st-form"><label class="rl-field" data-invalid={props.nameError ? "true" : undefined}><span>Project name</span><input value={form.name()} disabled={props.busy} onInput={(event) => form.setName(event.currentTarget.value)} /><Show when={props.nameError}><small data-tone="bad">{props.nameError}</small></Show></label><Show when={directorySource()}><div class="rl-source-tabs"><SharedRadioGroup label="Master Session source" options={[{ value: "existing", label: "Existing Session", icon: "chat" }, { value: "directory", label: "New Session in folder", icon: "folder-plus" }]} value={form.source()} disabled={props.busy} onChange={(value) => form.setSource(value === "directory" ? "directory" : "existing")} /></div></Show><Show when={form.source() === "directory"} fallback={<><h3>Master Session</h3><Show when={(props.candidates?.length ?? 0) > 4}><label class="rl-field"><span class="rl-input-icon"><Icon name="search" size={16} /><input type="search" aria-label="Search Sessions" placeholder="Title or Session ID" value={form.query()} onInput={(event) => form.setQuery(event.currentTarget.value)} /></span></label></Show><div class="rl-list" role="radiogroup" aria-label="Master Session"><For each={masterCandidates()} fallback={<p class="st-muted">No Sessions match.</p>}>{(candidate) => <button type="button" role="radio" class="rl-option" aria-checked={form.masterID() === candidate.id} disabled={props.busy} onClick={() => form.chooseMaster(candidate.id)}><span class="rl-option-text"><span>{candidate.title}</span></span><Show when={form.masterID() === candidate.id}><span class="rl-badge" data-status="supported">Master</span></Show></button>}</For></div></>}><h3>Workspace folder</h3><Show when={props.directories?.length}><div class="ws-row" role="group" aria-label="Workspace folders"><For each={props.directories}>{(entry) => <button type="button" class="rl-chip" title={entry.directory} aria-pressed={form.directory() === entry.directory} disabled={props.busy} onClick={() => form.setDirectory(entry.directory)}><Icon name="folder" size={14} />{entry.name ?? entry.directory}</button>}</For></div></Show><div class="ws-row"><label class="rl-field"><span>Folder path</span><input aria-label="Project folder path" placeholder="/path/to/folder" value={form.directory()} disabled={props.busy} onInput={(event) => form.setDirectory(event.currentTarget.value)} /></label><Show when={props.onBrowseFolder}><button type="button" class="rl-btn" disabled={props.busy} onClick={() => form.browse()}><Icon name="folder-plus" size={15} class="rl-ico" /> Browse / New folder…</button></Show></div><label class="rl-field"><span>Master Session title</span><input value={form.masterTitle()} placeholder="Defaults to project name" disabled={props.busy} onInput={(event) => form.setMasterTitle(event.currentTarget.value)} /></label></Show><Show when={props.candidates?.length}><h3>Member Sessions</h3><div class="rl-list" role="group" aria-label="Member Sessions"><For each={memberCandidates()}>{(candidate) => <label class="rl-option"><input type="checkbox" checked={form.memberIDs().includes(candidate.id)} disabled={props.busy} onChange={() => form.toggleMember(candidate.id)} /><span>{candidate.title}</span></label>}</For></div></Show><Show when={form.error()}><p role="alert" data-tone="bad">{form.error()}</p></Show><button type="button" class="rl-btn" data-tone="go" disabled={props.busy} onClick={() => form.submit()}>Create project</button><button type="button" class="rl-btn" disabled={props.busy} onClick={props.onCancelCreate}>Cancel</button></div></Show><Show when={props.projects.length} fallback={<p class="st-muted">No projects.</p>}><div class="st-split"><div class="ws-split ws-projects"><section class="st-section" data-part="st-coord-list"><header class="st-section-head"><h3>Projects</h3></header><div role="listbox" tabindex="0" class="rl-list" aria-label="Projects"><For each={props.projects}>{(project) => <button type="button" role="option" class="rl-option" aria-selected={project.id === props.selectedID} onClick={() => props.onSelect(project.id)}><span class="rl-option-text"><span>{project.name}</span><small>master {project.masterTitle} · {project.members.length} member{project.members.length === 1 ? "" : "s"}</small></span><span class="rl-option-meta">{project.active ? "Active" : "Paused"}</span></button>}</For></div></section><Show when={selected()}>{(project) => <section class="st-section" data-part="st-coord-detail"><header class="st-section-head"><h3>{project().name}</h3></header><p class="st-skill-state"><span class="st-chip" data-tone={project().active ? "ok" : "wait"}>{project().active ? "Active" : "Paused"}</span><span>{project().statusText} · revision {project().revision}</span></p><ul class="st-rows"><For each={[project().master, ...project().members]}>{(member, index) => <li class="st-row"><span aria-hidden="true">♙</span><span class="st-row-main"><span>{member.title}</span><small>{index() === 0 ? "Master" : "Member"}</small></span><span class="st-chip" data-tone={member.state === "running" ? "ok" : "wait"}>{member.state}</span></li>}</For></ul><dl class="rl-meta"><dt>Delegated decisions</dt><dd>{project().delegatedText ?? "None"}</dd></dl><Show when={props.concurrencyControl} fallback={<SharedRadioGroup label="Members running at once" options={[{ value: "1", label: "1" }, { value: "2", label: "2" }, { value: "4", label: "4" }, { value: "none", label: "No limit" }]} value={project().concurrency ?? "none"} disabled={props.busy} onChange={props.onChangeConcurrency} />}>{(control) => control()(project())}</Show><div class="st-actions"><p class="st-muted" data-part="st-coord-open-note">{project().openNote}</p><button type="button" class="rl-btn" data-tone="go" data-action-id="st-coord-open" disabled={props.busy} onClick={() => props.onOpenMaster(project().master.sessionID)}><Icon name="external" size={15} /> Open project chat</button></div><Show when={props.onDeleteProject}><div class="st-actions"><p class="st-muted">You confirm before the project is deleted.</p><button type="button" class="rl-btn" data-tone="danger" data-action-id="st-coord-delete" disabled={props.busy} onClick={() => props.onDeleteProject?.(project().id)}><Icon name="close" size={15} /> Delete project</button></div></Show></section>}</Show></div></div></Show></div>
}

export function SharedSessionsSurface(props: { readonly search: string; readonly searchError?: string; readonly filters: readonly { readonly value: string; readonly label: string; readonly count: number }[]; readonly filter: string; readonly pinning: boolean; readonly items: readonly { readonly id: string; readonly title: string; readonly hint: string; readonly meta: string; readonly pinned: boolean }[]; readonly selectedID?: string; readonly totalLoaded: number; readonly pinnedCount: number; readonly statusNote?: string; readonly hasMore?: boolean; readonly loadingMore?: boolean; readonly onNewSession: () => void; readonly onSearch: (value: string) => void; readonly onFilter: (value: string) => void; readonly onTogglePinMode: () => void; readonly onTogglePin?: (id: string, pinned: boolean) => void; readonly onSelect: (id: string) => void; readonly onLoadMore?: () => void }): JSX.Element {
  return <div class="ws-stack"><label class="rl-field" data-invalid={props.searchError ? "true" : undefined}><span>Search Sessions</span><span class="rl-input-icon"><Icon name="search" size={16} /><input type="search" value={props.search} placeholder="Title or workspace" onInput={(event) => props.onSearch(event.currentTarget.value)} /></span><Show when={props.searchError}><small data-tone="bad">{props.searchError}</small></Show></label><div class="ws-bar ws-chips"><SharedRadioGroup label="Filter by status" options={props.filters.map((filter) => ({ value: filter.value, label: `${filter.label} ${countFormat.format(filter.count)}` }))} value={props.filter} onChange={props.onFilter} /><button type="button" class="rl-icon" data-action-id="ws-list-pins" aria-label="Edit pins" aria-pressed={props.pinning} onClick={props.onTogglePinMode}><Icon name="pin" size={16} /></button><button type="button" class="rl-btn ws-new-session" data-action-id="ws-list-new" onClick={props.onNewSession}><Icon name="plus" size={14} /> New Session</button></div><p class="ws-line"><span data-part="ws-list-count">Showing {countFormat.format(props.items.length)} of {countFormat.format(props.totalLoaded)}</span><span aria-hidden="true"> · </span><span data-part="ws-list-pinned">{countFormat.format(props.pinnedCount)} pinned</span><Show when={props.statusNote}><span> · {props.statusNote}</span></Show></p><div role="listbox" tabindex="0" class="rl-list" aria-label="Sessions"><For each={props.items}>{(item) => <div role="option" tabindex="0" class="rl-option" data-status={/Waiting/i.test(item.hint) ? "waiting" : /Running/i.test(item.hint) ? "running" : undefined} aria-selected={item.id === props.selectedID} onClick={() => props.onSelect(item.id)} onKeyDown={(event) => { if (event.target === event.currentTarget && (event.key === "Enter" || event.key === " ")) { event.preventDefault(); props.onSelect(item.id) } }}><span class="rl-option-text"><span class="rl-option-name"><span aria-hidden="true"><Icon name={item.pinned ? "pin" : "chat"} size={14} /></span><span>{item.title}</span></span><small>{item.hint}</small></span><span class="rl-option-end"><span class="rl-option-meta">{item.meta}</span><Show when={props.onTogglePin}><button type="button" class="rl-btn rl-pin-btn" aria-label={`${item.pinned ? "Unpin" : "Pin"} ${item.title}`} data-pinned={item.pinned ? "true" : undefined} onClick={(event) => { event.stopPropagation(); props.onTogglePin?.(item.id, !item.pinned) }}><Icon name="pin" size={14} /></button></Show></span></div>}</For></div><Show when={!props.items.length}><p class="rl-list-empty">No Sessions match this filter.</p></Show><Show when={props.hasMore}><div class="ws-row"><button type="button" class="rl-btn" data-action-id="ws-list-more" disabled={props.loadingMore} onClick={props.onLoadMore}>Load older Sessions</button><span class="ws-line" data-part="ws-list-more-status">{props.loadingMore ? "Loading the next page…" : "Newest first · older pages load on request"}</span></div></Show></div>
}

export type SharedWorkspaceItem = { readonly key?: string; readonly projectID: string; readonly name: string; readonly directory: string; readonly sessions: number; readonly topLevelSummary: string; readonly childSummary: string; readonly copies: readonly { readonly name: string; readonly directory: string; readonly label?: string }[] }
export type SharedDirectoryExplorerProps = {
  readonly directory: string
  readonly rootDirectory: string
  readonly parent?: string | null
  readonly entries: ReadonlyArray<{ readonly name: string; readonly path: string; readonly kind: "directory" | "file" }>
  readonly truncated?: boolean
  readonly loading?: boolean
  readonly error?: string
  readonly showHidden?: boolean
  readonly onNavigate: (directory: string) => void
  readonly onToggleHidden?: () => void
  readonly onCreateFolder?: (parentDirectory: string) => void
  readonly onStartChatInFolder?: (directory: string) => void
}

function SharedDirectoryExplorer(props: { readonly explorer: SharedDirectoryExplorerProps }): JSX.Element {
  const [filter, setFilter] = createSignal("")
  const entries = () => { const needle = filter().trim().toLowerCase(); return props.explorer.entries.filter((entry) => !needle || entry.name.toLowerCase().includes(needle)) }
  return <section class="ws-section rl-explorer" aria-label="Workspace files"><div class="ws-section-head"><h3>FILES</h3><div class="ws-row"><button type="button" class="rl-btn" disabled={!props.explorer.parent || props.explorer.loading} onClick={() => { if (props.explorer.parent) props.explorer.onNavigate(props.explorer.parent) }}><Icon name="arrow-up" size={14} /> Up</button><button type="button" class="rl-btn" disabled={props.explorer.directory === props.explorer.rootDirectory || props.explorer.loading} onClick={() => props.explorer.onNavigate(props.explorer.rootDirectory)}><Icon name="folder" size={14} /> Root</button><Show when={props.explorer.onToggleHidden}><button type="button" class="rl-btn" aria-pressed={props.explorer.showHidden ?? false} onClick={() => props.explorer.onToggleHidden?.()}>Hidden</button></Show><Show when={props.explorer.onCreateFolder}><button type="button" class="rl-btn" disabled={props.explorer.loading} onClick={() => props.explorer.onCreateFolder?.(props.explorer.directory)}><Icon name="folder-plus" size={14} /> New folder</button></Show><Show when={props.explorer.onStartChatInFolder}><button type="button" class="rl-btn" onClick={() => props.explorer.onStartChatInFolder?.(props.explorer.directory)}><Icon name="chat" size={14} /> Chat here</button></Show></div></div><p class="ws-line"><code>{props.explorer.directory}</code></p><label class="rl-field"><span class="rl-input-icon"><Icon name="search" size={16} /><input type="search" aria-label="Filter files" placeholder="Filter this folder" value={filter()} onInput={(event) => setFilter(event.currentTarget.value)} /></span></label><Show when={props.explorer.error}><p role="alert" data-tone="bad">{props.explorer.error}</p></Show><Show when={props.explorer.loading}><p class="ws-line" role="status">Loading folder…</p></Show><ul class="ws-items rl-explorer-list" data-part="ws-files"><For each={entries()} fallback={<li class="ws-line">{filter().trim() ? "No entries match." : "This folder is empty."}</li>}>{(entry) => <li>{entry.kind === "directory" ? <button type="button" class="rl-option" data-kind="directory" data-path={entry.path} disabled={props.explorer.loading} onClick={() => props.explorer.onNavigate(entry.path)}><Icon name="folder" size={14} /><span>{entry.name}</span><Icon name="chevron-right" size={14} /></button> : <span class="rl-option" data-kind="file" data-path={entry.path}><Icon name="file" size={14} /><span>{entry.name}</span></span>}</li>}</For></ul><Show when={props.explorer.truncated}><p class="ws-line">Showing the first {countFormat.format(props.explorer.entries.length)} entries.</p></Show></section>
}

export function SharedWorkspacesSurface(props: { readonly workspaces: readonly SharedWorkspaceItem[]; readonly selectedID?: string; readonly currentSession?: { readonly title: string; readonly directory: string; readonly workspace: string }; readonly copiesBusy?: boolean; readonly copiesStatus?: string; readonly copyForm?: JSX.Element; readonly onSelect: (projectID: string) => void; readonly onRefreshCopies?: (workspace: SharedWorkspaceItem) => void; readonly onOpenCreateCopy?: () => void; readonly onStartChat?: (directory: string) => void; readonly onForgetWorkspace?: (workspace: SharedWorkspaceItem) => void; readonly searchQuery?: string; readonly onSearchChange?: (query: string) => void; readonly onOpenFolder?: () => void; readonly onCreateFolder?: () => void; readonly explorer?: SharedDirectoryExplorerProps }): JSX.Element {
  const [localQuery, setLocalQuery] = createSignal("")
  const query = () => props.searchQuery ?? localQuery()
  const setQuery = (value: string) => { setLocalQuery(value); props.onSearchChange?.(value) }
  const visible = () => { const needle = query().trim().toLowerCase(); return props.workspaces.filter((workspace) => !needle || [workspace.name, workspace.directory, ...workspace.copies.flatMap((copy) => [copy.name, copy.directory])].some((text) => text.toLowerCase().includes(needle))) }
  const entryKey = (workspace: SharedWorkspaceItem) => workspace.key ?? `${workspace.projectID}:${workspace.directory}`
  const isSelected = (workspace: SharedWorkspaceItem) => props.selectedID === entryKey(workspace)
  const selected = () => props.workspaces.find(isSelected)
  return <div class="ws-host ws-stack"><p class="ws-hint" data-part="ws-projects-scope">Each workspace is a folder Sessions run in on this Mac. A Project groups Sessions under one Master Session; it is separate and opens from the command palette.</p><div class="ws-location" data-part="ws-projects-location"><Icon name="folder" size={16} /><Show when={props.currentSession} fallback={<span class="ws-location__label">No Session is open.</span>}>{(session) => <><span class="ws-location__label">This Session <strong>{session().title}</strong></span><p>Location <code>{session().directory}</code> · workspace {session().workspace}</p></>}</Show></div><Show when={props.onOpenFolder || props.onCreateFolder}><div class="ws-row" data-part="ws-folder-actions"><Show when={props.onOpenFolder}><button type="button" class="rl-btn" onClick={() => props.onOpenFolder?.()}><Icon name="folder" size={14} class="rl-ico" /> Open folder…</button></Show><Show when={props.onCreateFolder}><button type="button" class="rl-btn" onClick={() => props.onCreateFolder?.()}><Icon name="folder-plus" size={14} class="rl-ico" /> New folder…</button></Show></div></Show><div class="ws-split ws-workspaces"><div class="ws-workspaces-list"><div class="rl-workspace-search"><span class="rl-input-icon"><Icon name="search" size={16} class="rl-ico" /><input type="search" aria-label="Search workspaces" placeholder="Search workspaces or paths..." value={query()} onInput={(event) => setQuery(event.currentTarget.value)} /></span><Show when={query()}><small class="ws-line" aria-live="polite">{countFormat.format(visible().length)} of {countFormat.format(props.workspaces.length)}</small><button type="button" class="rl-icon-button" aria-label="Clear workspace search" onClick={() => setQuery("")}><Icon name="close" size={14} /></button></Show></div><div role="listbox" tabindex="0" class="rl-list" aria-label="Workspaces"><For each={visible()}>{(workspace) => <button type="button" role="option" class="rl-option" aria-selected={isSelected(workspace)} onClick={() => props.onSelect(entryKey(workspace))}><span class="rl-option-text"><span class="rl-option-name"><span aria-hidden="true"><Icon name="folder" size={15} /></span><span>{workspace.name}</span></span><Show when={workspace.name !== workspace.directory}><small>{workspace.directory}</small></Show></span><span class="rl-option-meta">{countFormat.format(workspace.sessions)} {workspace.sessions === 1 ? "Session" : "Sessions"}</span></button>}</For></div><Show when={query().trim() && !visible().length}><div class="ws-empty" role="status"><p>No workspaces match "{query().trim()}".</p><button type="button" class="rl-btn" onClick={() => setQuery("")}>Clear search</button></div></Show></div><Show when={selected()}>{(workspace) => <div class="ws-stack ws-workspaces-detail"><h3 class="ws-title">{workspace().name}</h3><dl class="rl-meta"><dt>Directory</dt><dd><code>{workspace().directory}</code></dd><dt>Top-level Sessions</dt><dd>{workspace().topLevelSummary}</dd><dt>Child Sessions</dt><dd>{workspace().childSummary}</dd></dl><section class="ws-section" aria-label="Copies"><div class="ws-section-head"><h3>Copies</h3><div class="ws-row"><button type="button" class="rl-btn" disabled={props.copiesBusy || !props.onRefreshCopies} onClick={() => props.onRefreshCopies?.(workspace())}><Icon name="refresh" size={14} /> Refresh</button><Show when={props.onOpenCreateCopy}><button type="button" class="rl-btn" disabled={props.copiesBusy} onClick={props.onOpenCreateCopy}><Icon name="plus" size={14} /> New copy</button></Show><Show when={props.onStartChat}><button type="button" class="rl-btn" onClick={() => props.onStartChat?.(workspace().directory)}><Icon name="chat" size={14} /> Start chat</button></Show></div></div><ul class="ws-items" data-part="ws-copies"><For each={workspace().copies}>{(copy) => <li><span><strong>{copy.name}</strong><Show when={copy.name !== copy.directory}><code>{copy.directory}</code></Show></span><Show when={copy.label}><small>{copy.label}</small></Show></li>}</For></ul>{props.copyForm}<p class="ws-line" data-part="ws-copies-status">{props.copiesStatus ?? `${workspace().copies.length} ${workspace().copies.length === 1 ? "copy" : "copies"} · each copy is its own directory`}</p></section><Show when={props.explorer}>{(explorer) => <SharedDirectoryExplorer explorer={explorer()} />}</Show><Show when={props.onForgetWorkspace}><button type="button" class="rl-btn" data-tone="danger" data-action-id="ws-projects-forget" disabled={props.copiesBusy} onClick={() => props.onForgetWorkspace?.(workspace())}><Icon name="close" size={14} /> Forget workspace…</button></Show></div>}</Show></div></div>
}

export function SharedUsageSurface(props: { readonly phase: "ready" | "preparing" | "error"; readonly statusText: string; readonly ranges: readonly { readonly value: string; readonly label: string }[]; readonly range: string; readonly rangeLabel: string; readonly requests: string; readonly inputTokens: string; readonly outputTokens: string; readonly estimatedCost: string; readonly detailLine?: string; readonly refreshing?: boolean; readonly quotas?: readonly { readonly key?: string; readonly provider: string; readonly account?: string; readonly status?: string; readonly statusTone?: "ok" | "warn" | "bad" | "muted"; readonly note?: string; readonly windows: readonly { readonly label: string; readonly group?: string; readonly used?: number; readonly detail: string; readonly reset?: string; readonly level?: "ok" | "warn" | "danger" }[] }[]; readonly models?: readonly { readonly name: string; readonly detail: string; readonly value: string }[]; readonly modelsNote?: string; readonly onRange: (value: string) => void; readonly onRefresh: () => void }): JSX.Element {
  return <div class="relay-settings st-stack"><div class="st-status" data-part="st-usage-state" data-phase={props.phase} role="status"><span class="st-chip" data-tone={props.phase === "error" ? "bad" : props.phase === "preparing" ? "wait" : "ok"}>{props.phase === "error" ? "Error" : props.phase === "preparing" ? "Preparing" : "Ready"}</span><span>{props.statusText}</span><Show when={props.phase === "preparing"}><div class="rl-indeterminate" aria-hidden="true"><span /></div></Show></div><div class="st-toolbar"><SharedRadioGroup label="Usage period" options={props.ranges} value={props.range} onChange={props.onRange} /><button type="button" class="rl-btn" data-action-id="st-usage-refresh" disabled={props.refreshing} onClick={props.onRefresh}><Icon name="refresh" size={15} /> Refresh</button></div><div class="st-tiles" data-part="st-usage-summary"><For each={[["zap", `Requests · ${props.rangeLabel}`, props.requests], ["arrow-up", "Input tokens", props.inputTokens], ["arrow-down", "Output tokens", props.outputTokens], ["usage", "Estimated cost", props.estimatedCost]] as const}>{([icon, label, value]) => <div class="st-tile"><small><Icon name={icon} size={16} />{label}</small><strong>{value}</strong></div>}</For></div><Show when={props.detailLine}><p class="st-live" data-part="st-usage-live">{props.detailLine}</p></Show><section class="st-section" data-part="st-quota"><header class="st-section-head"><h3><Icon name="shield" size={16} />Provider quota windows</h3></header><div class="st-quota-grid"><For each={props.quotas}>{(quota) => <div class="st-quota" data-tone={quota.statusTone}><div class="st-quota-head"><div class="st-quota-ident"><p class="st-quota-provider">{quota.provider}</p><Show when={quota.account}>{(account) => <span class="st-quota-account">{account()}</span>}</Show></div><Show when={quota.status}>{(status) => <span class="st-chip" data-tone={quota.statusTone === "warn" ? "wait" : quota.statusTone === "bad" ? "bad" : quota.statusTone === "muted" ? "muted" : "ok"}>{status()}</span>}</Show></div><Show when={quota.windows.length}><div class="st-quota-windows"><For each={quota.windows}>{(window, index) => <><Show when={window.group && window.group !== quota.windows[index() - 1]?.group}><p class="st-quota-group">{window.group}</p></Show><div class="st-quota-row" data-reported={window.used !== undefined ? "true" : "false"} data-level={window.level}><span class="st-quota-label">{window.label}</span><Show when={window.used !== undefined} fallback={<div class="st-track-empty" aria-hidden="true" />}><div class="rl-progress" data-level={window.level} role="progressbar" aria-label={`${quota.provider}${quota.account ? ` (${quota.account})` : ""} ${window.label} used`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(window.used! * 10) / 10}><span style={{ width: `${Math.max(0, Math.min(100, window.used!))}%` }} /></div></Show><span class="st-quota-value">{window.detail}<Show when={window.reset}>{(reset) => <small class="st-quota-reset"> · {reset()}</small>}</Show></span></div></>}</For></div></Show><Show when={quota.note}>{(note) => <p class="st-quota-note">{note()}</p>}</Show></div>}</For></div><Show when={props.quotas && props.quotas.length === 0}><p class="st-muted">No provider quotas reported.</p></Show></section><Show when={props.models?.length}><section class="st-section" data-part="st-usage-models"><header class="st-section-head"><h3><Icon name="cpu" size={16} />Models</h3></header><ul class="st-rows"><For each={props.models}>{(model) => <li class="st-row"><span class="st-row-main"><span>{model.name}</span><small>{model.detail}</small></span><span>{model.value}</span></li>}</For></ul><Show when={props.modelsNote}><p class="st-muted">{props.modelsNote}</p></Show></section></Show></div>
}

function SharedSettingsSwitch(props: { readonly label: string; readonly hint?: string; readonly checked: boolean; readonly disabled?: boolean; readonly onChange: (value: boolean) => void }): JSX.Element {
  return <div class="rl-switch-row"><span class="rl-switch-text"><span>{props.label}</span><Show when={props.hint}><small>{props.hint}</small></Show></span><button type="button" class="rl-switch" role="switch" aria-label={props.label} aria-checked={props.checked} disabled={props.disabled} onClick={() => props.onChange(!props.checked)}><span class="rl-switch-track" aria-hidden="true"><i /></span></button></div>
}

export function SharedSettingsSurface(props: { readonly animations: boolean; readonly keepAwakeChecked: boolean; readonly keepAwakeDisabled?: boolean; readonly keepAwakeStatus?: "supported" | "partial" | "unsupported"; readonly keepAwakeDetail: string; readonly telemetryConsent: "undecided" | "enabled" | "disabled"; readonly telemetryNote: string; readonly telemetryBusy?: boolean; readonly latencySamples?: readonly { readonly label: string; readonly detail: string; readonly value: string }[]; readonly notificationsContent?: JSX.Element; readonly savedPermissionsContent?: JSX.Element; readonly closeAppContent?: JSX.Element; readonly notificationsOpen?: boolean; readonly savedPermissionsOpen?: boolean; readonly closeAppOpen?: boolean; readonly theme?: "system" | "light" | "dark"; readonly onThemeChange?: (theme: "system" | "light" | "dark") => void; readonly leadingSections?: JSX.Element; readonly colorSchemeControl?: JSX.Element; readonly hideKeepAwakeSection?: boolean; readonly onToggleAnimations: (enabled: boolean) => void; readonly onToggleKeepAwake: (enabled: boolean) => void; readonly onDecideTelemetry: (enabled: boolean) => void; readonly onToggleNotifications: () => void; readonly onToggleSavedPermissions: () => void; readonly onToggleCloseApp: () => void }): JSX.Element {
  return <div class="relay-settings st-stack st-ledger-settings">
    {props.leadingSections}
    <section class="st-section" data-part="st-appearance"><header class="st-section-head"><h3><Icon name="sparkles" size={16} />Appearance</h3></header><Show when={props.colorSchemeControl} fallback={<Show when={props.theme !== undefined && props.onThemeChange !== undefined}><div class="rl-switch-row" data-part="st-theme"><span class="rl-switch-text"><span>Theme</span></span><SharedRadioGroup label="Theme" value={props.theme!} options={[{ value: "light", label: "Light", icon: "sun" }, { value: "dark", label: "Dark", icon: "moon" }, { value: "system", label: "System", icon: "monitor" }]} onChange={(value) => props.onThemeChange!(value as "system" | "light" | "dark")} /></div></Show>}><div class="rl-switch-row" data-part="st-color-scheme"><span class="rl-switch-text"><span>Color scheme</span></span>{props.colorSchemeControl}</div></Show><SharedSettingsSwitch label="Animations" hint="Desktop preference · reduced motion always wins" checked={props.animations} onChange={props.onToggleAnimations} /></section>
    <Show when={!props.hideKeepAwakeSection}><section class="st-section" data-part="st-keep-awake"><header class="st-section-head"><h3><Icon name="zap" size={16} />Keep awake</h3></header><SharedSettingsSwitch label="Keep this Mac awake" checked={props.keepAwakeChecked} disabled={props.keepAwakeDisabled} onChange={props.onToggleKeepAwake} /><p class="st-muted" id="st-keep-awake-state" data-part="st-keep-awake-state">{props.keepAwakeStatus === "unsupported" ? "Keep awake is unsupported on this machine." : props.keepAwakeDetail}</p></section></Show>
    <section class="st-section" data-part="st-notify"><header class="st-section-head"><h3><Icon name="bell" size={16} />Notifications</h3></header><p class="st-muted" data-part="st-push-state">This Mac signals attention in the terminal when a Session waits or fails. Push and the notification center are web features.</p><div class="st-actions"><button type="button" class="rl-btn" data-action-id="st-open-notifications" aria-expanded={props.notificationsOpen} onClick={props.onToggleNotifications}>Open notifications</button></div><Show when={props.notificationsContent}>{(content) => <div class="st-disclosure-card">{content()}</div>}</Show></section>
    <section class="st-section" data-part="st-permissions"><header class="st-section-head"><h3><Icon name="shield" size={16} />Permissions</h3></header><p class="st-muted">Rules you saved with Always allow, per action and resource.</p><div class="st-actions"><button type="button" class="rl-btn" data-action-id="st-saved-permissions" aria-expanded={props.savedPermissionsOpen} onClick={props.onToggleSavedPermissions}>Review saved rules</button></div><Show when={props.savedPermissionsContent}>{(content) => <div class="st-disclosure-card">{content()}</div>}</Show></section>
    <section class="st-section" data-part="st-close"><header class="st-section-head"><h3><Icon name="monitor" size={16} />App</h3></header><p class="st-muted">Review what closing YCoding means for its server.</p><div class="st-actions"><button type="button" class="rl-btn st-full-btn" data-action-id="st-open-quit" aria-expanded={props.closeAppOpen} onClick={props.onToggleCloseApp}>Close app</button></div><Show when={props.closeAppContent}>{(content) => <div class="st-disclosure-card">{content()}</div>}</Show></section>
    <section class="st-section" data-part="st-telemetry"><header class="st-section-head"><h3><Icon name="usage" size={16} />Latency diagnostics</h3></header><Show when={props.telemetryConsent !== "undecided"} fallback={<div class="st-consent"><p>Share latency diagnostics from this Mac? They time prompt admission, the first streamed token and transcript loads.</p><p class="st-muted" id="st-telemetry-note">{props.telemetryNote}</p><div class="st-actions"><button type="button" class="rl-btn" data-tone="go" disabled={props.telemetryBusy} onClick={() => props.onDecideTelemetry(true)}>Share</button><button type="button" class="rl-btn" disabled={props.telemetryBusy} onClick={() => props.onDecideTelemetry(false)}>Don't share</button></div></div>}><SharedSettingsSwitch label="Share latency diagnostics" checked={props.telemetryConsent === "enabled"} disabled={props.telemetryBusy} onChange={props.onDecideTelemetry} /><p class="st-muted">{props.telemetryNote}</p><Show when={props.latencySamples?.length}><ul class="st-rows"><For each={props.latencySamples}>{(sample) => <li class="st-row"><span class="st-row-main"><span>{sample.label}</span><small>{sample.detail}</small></span><span>{sample.value}</span></li>}</For></ul></Show></Show></section>
  </div>
}
